export const GLOSSARY_SHARD = Object.freeze({"all-time-high":{"slug":"all-time-high","cat":"basics","en":"All-time high (ATH)","contentLocale":"id","term":"All-time high (ATH)","aka":["ATH","harga tertinggi sepanjang masa","rekor harga"],"short":"All-time high (ATH) adalah harga tertinggi yang pernah dicapai sebuah aset sejak mulai diperdagangkan.","body":[["Saat harga menembus ATH sebelumnya, tidak ada lagi pemegang yang sedang rugi di atas harga itu. Hal ini sering memicu perhatian media, masuknya pembeli baru, dan ",["FOMO","fomo"],". Kebalikannya adalah all-time low (ATL), harga terendah sepanjang masa."],["Situs data dan exchange bisa mencatat ATH yang sedikit berbeda karena memakai sumber harga dan ",["pasangan perdagangan","trading-pair"]," berbeda, misalnya ",["BTC","bitcoin"],"/USD, BTC/",["USDT","usdt"],", atau BTC/IDR. Harga ATH dalam rupiah bisa tercapai lebih dulu daripada dalam dolar jika rupiah melemah."],"Banyak trader juga melihat jarak harga saat ini dari ATH, misalnya turun 60% dari ATH. Angka ini membantu memahami seberapa jauh koreksi, tetapi tidak menunjukkan apakah harga akan kembali ke puncak itu."],"example":"Misalkan sebuah koin mencatat ATH di 4,00 USDT lalu turun ke 1,00 USDT. Penurunannya 75% dari ATH. Untuk kembali ke ATH, harga harus naik 300%, dari 1,00 menjadi 4,00 USDT. Jika Anda membeli di 3,20 USDT, posisi Anda sudah rugi 68,75% di harga 1,00, dan baru impas setelah harga naik 220% ke 3,20.","mistakes":["Membeli besar-besaran tepat saat ATH baru hanya karena ramai diberitakan.","Menganggap koin yang turun jauh dari ATH pasti murah dan pasti akan kembali.","Membandingkan ATH dari sumber atau pasangan mata uang yang berbeda."],"faq":[{"q":"Apa arti ATH dalam kripto?","a":"ATH adalah singkatan all-time high, harga tertinggi yang pernah dicapai sebuah aset. Kebalikannya adalah ATL, harga terendah sepanjang masa."},{"q":"Apakah membeli di ATH itu buruk?","a":"Tidak selalu, karena harga bisa terus membuat ATH baru dalam tren naik. Namun risiko koreksi tajam lebih besar, jadi ukuran posisi dan stop loss menjadi penting."}],"title":"Apa itu ATH (all-time high) di kripto?","description":"Arti ATH atau all-time high di kripto, kenapa rekor harga memicu FOMO, dan cara membaca jarak harga dari puncaknya.","related":[["bull-market","Bull market (pasar bullish)","Bull market adalah periode ketika harga aset di pasar cenderung naik secara berkelanjutan selama berminggu-minggu hingga bertahun-tahun, disertai sentimen optimis dan minat beli yang tinggi."],["fomo","FOMO (fear of missing out)","FOMO atau fear of missing out adalah rasa takut ketinggalan keuntungan yang mendorong trader membeli secara impulsif setelah harga sudah naik tajam."],["volatility","Volatility (volatilitas)","Volatilitas adalah ukuran seberapa besar dan seberapa cepat harga sebuah aset bergerak naik turun dalam periode tertentu."],["support-and-resistance","Support dan resistance","Support dan resistance adalah area harga di mana penurunan cenderung tertahan karena banyak pembeli (support) atau kenaikan cenderung tertahan karena banyak penjual (resistance)."]],"lesson":null,"coin":null,"tool":"/coins","cta":false},"coin-margined-futures":{"slug":"coin-margined-futures","cat":"derivatives","en":"Coin-margined (inverse) futures","contentLocale":"id","term":"Futures coin-margined (inverse futures)","aka":["coin-M","inverse futures","kontrak inverse","futures margin koin"],"short":"Futures coin-margined adalah kontrak futures yang memakai koin kripto seperti BTC sebagai margin dan mata uang penyelesaian, sehingga untung dan rugi Anda dihitung dalam koin tersebut, bukan dalam USDT.","body":[["Kontrak ini sering disebut inverse karena nilai kontraknya biasanya ditetapkan dalam dolar, misalnya 100 USD per kontrak, sedangkan margin dan PnL dalam koin. Akibatnya, hubungan antara harga dan PnL tidak linear: keuntungan dalam ",["BTC","bitcoin"]," dari long mengecil per dolar saat harga terus naik."],["Daya tarik utamanya bagi pemegang koin jangka panjang. Penambang atau holder BTC bisa memakai BTC yang sudah dimiliki sebagai margin tanpa menukarnya ke ",["stablecoin","stablecoin"],". Namun, risikonya berlapis: jika Anda long dengan margin BTC dan harga turun, Anda rugi pada posisi sekaligus nilai margin Anda ikut turun."],"Sebaliknya, short coin-margined dengan ukuran yang sama dengan BTC yang Anda pegang bisa mengunci nilai dolar kepemilikan Anda. Nama produk dan ukuran kontrak berbeda tiap exchange, jadi baca spesifikasinya."],"example":"Anda menyetor 0,1 BTC sebagai margin saat BTC di 50.000 USD, senilai 5.000 USD, lalu long 100 kontrak inverse bernilai 100 USD per kontrak, total 10.000 USD. Posisi itu setara 10.000 dibagi 50.000 = 0,2 BTC. Jika BTC naik ke 55.000, PnL dalam BTC = 10.000 x (1/50.000 - 1/55.000) = sekitar 0,01818 BTC. Margin Anda menjadi sekitar 0,1182 BTC, bernilai sekitar 6.500 USD.","mistakes":["Lupa bahwa saat long dengan margin koin, penurunan harga memukul posisi dan nilai margin sekaligus.","Menghitung PnL inverse seperti kontrak linear, padahal rumusnya memakai kebalikan harga.","Mengira ukuran kontrak sama di semua exchange tanpa memeriksa nilai per kontrak."],"faq":[{"q":"Apa beda coin-margined dan USDT-margined?","a":"Coin-margined memakai koin seperti BTC sebagai margin dan menghitung PnL dalam koin. USDT-margined memakai USDT sebagai margin dan menghitung PnL dalam USDT secara linear."},{"q":"Siapa yang biasanya memakai futures coin-margined?","a":"Pemegang koin jangka panjang dan penambang yang ingin memakai koinnya sebagai margin atau melindungi nilai dolar kepemilikan mereka tanpa menjual ke stablecoin."}],"title":"Apa itu coin-margined futures? Arti kontrak inverse","description":"Pahami futures coin-margined atau inverse: margin dalam BTC, cara hitung PnL non-linear, kegunaan untuk hedging, dan risikonya.","related":[["usdt-margined-futures","Futures USDT-margined (linear futures)","Futures USDT-margined adalah kontrak futures yang memakai stablecoin USDT sebagai margin dan mata uang penyelesaian, sehingga untung dan rugi dihitung langsung dalam USDT secara linear."],["perpetual-futures","Kontrak berjangka perpetual (perpetual futures)","Kontrak berjangka perpetual adalah kontrak futures tanpa tanggal jatuh tempo yang harganya dijaga tetap dekat dengan harga spot melalui pembayaran funding rate berkala antara posisi long dan short."],["unrealized-pnl","Unrealized PnL (laba/rugi belum terealisasi)","Unrealized PnL adalah keuntungan atau kerugian di atas kertas dari posisi yang masih terbuka, dihitung dari selisih harga masuk dan harga acuan saat ini, dan baru menjadi nyata setelah posisi ditutup."],["hedging","Hedging (lindung nilai)","Hedging adalah strategi membuka posisi yang berlawanan dengan aset atau posisi yang Anda pegang untuk mengurangi risiko kerugian akibat pergerakan harga, dengan konsekuensi potensi untungnya ikut berkurang."]],"lesson":{"id":"E18","slug":"spot-vs-futures","ep":18,"title":"Spot vs futures: Anda tidak membeli hal yang sama"},"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":false},"hedging":{"slug":"hedging","cat":"derivatives","en":"Hedging","contentLocale":"id","term":"Hedging (lindung nilai)","aka":["lindung nilai","hedge","hedging kripto"],"short":"Hedging adalah strategi membuka posisi yang berlawanan dengan aset atau posisi yang Anda pegang untuk mengurangi risiko kerugian akibat pergerakan harga, dengan konsekuensi potensi untungnya ikut berkurang.","body":[["Bentuk hedging paling umum di kripto adalah memegang koin di spot lalu membuka short dengan ukuran sama di futures. Jika harga turun, kerugian spot diimbangi keuntungan short; jika harga naik, sebaliknya. Nilai portofolio Anda dalam ",["USDT","usdt"]," relatif terkunci selama hedge berjalan."],"Hedging juga bisa dilakukan sebagian, misalnya hanya melindungi 50% kepemilikan, atau dengan opsi put yang memberi perlindungan di bawah harga tertentu sambil tetap membiarkan potensi naik. Pilihan alatnya tergantung biaya, durasi, dan seberapa besar risiko yang ingin Anda kurangi.",["Hedging tidak gratis. Ada ",["biaya trading","maker-taker-fees"],", ",["funding rate","funding-rate"]," di ",["perpetual","perpetual-futures"],", premi opsi, dan risiko basis, yaitu perbedaan gerak antara harga spot dan kontrak. Hedging juga bukan alasan untuk menunda keputusan: jika Anda yakin ingin keluar, menjual sering lebih sederhana."]],"example":"Anda memegang 50 SOL di spot saat harga 160 USDT, nilai 8.000 USDT, dan ingin melindunginya selama dua minggu. Anda membuka short 50 SOL di perpetual dengan margin 2.000 USDT (4x). Jika SOL turun ke 130, spot rugi 1.500 USDT dan short untung 1.500 USDT, sehingga nilai gabungan tetap sekitar 8.000. Jika funding rata-rata 0,01% per 8 jam dan dibayar ke pihak short, Anda bahkan menerima sekitar 42 kali 0,8 USDT, kira-kira 34 USDT, selama 14 hari.","mistakes":["Membuka hedge dengan ukuran berbeda dari aset yang dilindungi sehingga masih ada risiko arah.","Memakai leverage tinggi di posisi short hedge sehingga short dilikuidasi saat harga naik, padahal spotnya untung.","Melupakan funding rate dan biaya yang terus berjalan selama hedge dipertahankan."],"faq":[{"q":"Bagaimana cara hedging kripto yang paling sederhana?","a":"Pegang koin di spot dan buka short dengan jumlah koin yang sama di futures dengan leverage rendah. Selama hedge berjalan, nilai gabungan Anda relatif stabil terhadap pergerakan harga."},{"q":"Apakah hedging menghilangkan semua risiko?","a":"Tidak. Masih ada risiko basis, biaya funding, risiko likuidasi pada posisi futures, dan risiko platform. Hedging mengurangi risiko harga, bukan menghapus semua risiko."}],"title":"Apa itu hedging di kripto? Arti lindung nilai dan contohnya","description":"Pelajari hedging atau lindung nilai di kripto: cara melindungi aset spot dengan futures atau opsi, contoh hitungan, dan biayanya.","related":[["short-selling","Short selling (jual short)","Short selling adalah strategi mendapat untung dari penurunan harga dengan menjual aset lebih dulu, lalu membelinya kembali di harga lebih rendah untuk menutup posisi."],["perpetual-futures","Kontrak berjangka perpetual (perpetual futures)","Kontrak berjangka perpetual adalah kontrak futures tanpa tanggal jatuh tempo yang harganya dijaga tetap dekat dengan harga spot melalui pembayaran funding rate berkala antara posisi long dan short."],["options","Opsi kripto (crypto options)","Opsi kripto adalah kontrak yang memberi pembelinya hak, tetapi bukan kewajiban, untuk membeli (call) atau menjual (put) aset kripto pada harga tertentu (strike) sampai atau pada tanggal jatuh tempo, dengan membayar premi."],["portfolio-margin","Portfolio margin","Portfolio margin adalah mode margin yang menghitung kebutuhan jaminan berdasarkan risiko gabungan seluruh portofolio, sehingga posisi yang saling mengimbangi bisa membutuhkan margin jauh lebih kecil."]],"lesson":{"id":"E18","slug":"spot-vs-futures","ep":18,"title":"Spot vs futures: Anda tidak membeli hal yang sama"},"coin":null,"tool":null,"cta":false},"options":{"slug":"options","cat":"derivatives","en":"Crypto options","contentLocale":"id","term":"Opsi kripto (crypto options)","aka":["options","opsi","call option","put option"],"short":"Opsi kripto adalah kontrak yang memberi pembelinya hak, tetapi bukan kewajiban, untuk membeli (call) atau menjual (put) aset kripto pada harga tertentu (strike) sampai atau pada tanggal jatuh tempo, dengan membayar premi.","body":["Pembeli opsi membayar premi di awal. Kerugian maksimalnya adalah premi itu, sementara potensi keuntungannya bisa besar jika harga bergerak sesuai arah. Penjual opsi menerima premi, tetapi menanggung kewajiban jika opsi bernilai saat jatuh tempo, sehingga risikonya bisa jauh lebih besar dan biasanya membutuhkan margin.",["Harga premi dipengaruhi jarak harga saat ini ke strike, sisa waktu, dan ",["volatilitas","volatility"]," yang diperkirakan pasar (implied volatility). Semakin dekat jatuh tempo, nilai waktu opsi menyusut. Kebanyakan opsi kripto bergaya Eropa, artinya hanya bisa dieksekusi saat jatuh tempo, dan diselesaikan secara tunai."],["Deribit dikenal sebagai pasar opsi kripto terbesar, dan exchange seperti OKX, Bybit, serta Binance juga menyediakan opsi. Produk seperti ",["dual investment","dual-investment"]," pada dasarnya juga dibangun dari penjualan opsi. Spesifikasi, ukuran kontrak, dan jadwal jatuh tempo berbeda di tiap platform."]],"example":[["BTC","bitcoin"]," diperdagangkan di 60.000 ",["USDT","usdt"],". Anda membeli 0,1 kontrak call dengan strike 65.000 yang jatuh tempo dalam 30 hari, dengan premi 1.500 USDT per BTC, jadi Anda membayar 150 USDT. Jika saat jatuh tempo BTC di 70.000, opsi bernilai (70.000 - 65.000) x 0,1 = 500 USDT, untung bersih 350 USDT. Jika BTC di 65.000 atau lebih rendah, opsi berakhir tanpa nilai dan kerugian Anda tepat 150 USDT. Titik impasnya 66.500."],"mistakes":["Membeli opsi yang sangat jauh dari harga hanya karena preminya murah, padahal peluang bernilai saat jatuh tempo kecil.","Menjual opsi demi premi tanpa memahami bahwa kerugiannya bisa jauh melebihi premi yang diterima.","Mengabaikan penyusutan nilai waktu menjelang jatuh tempo."],"faq":[{"q":"Apa beda opsi dan futures?","a":"Futures mewajibkan kedua pihak menanggung untung dan rugi dari pergerakan harga. Opsi memberi pembelinya hak tanpa kewajiban, dengan kerugian maksimal sebesar premi yang dibayar."},{"q":"Apa itu call dan put?","a":"Call memberi hak membeli di harga strike dan bernilai saat harga naik di atas strike. Put memberi hak menjual di harga strike dan bernilai saat harga turun di bawahnya."}],"title":"Apa itu opsi kripto? Arti call, put, strike, dan premi","description":"Pahami opsi kripto: arti call dan put, strike, premi, jatuh tempo, contoh hitungan untung-rugi, dan beda opsi dengan futures.","related":[["futures-contract","Kontrak futures (kontrak berjangka)","Kontrak futures adalah perjanjian untuk membeli atau menjual aset pada harga yang disepakati, sehingga Anda bisa mengambil posisi naik (long) atau turun (short) tanpa harus memegang asetnya langsung."],["hedging","Hedging (lindung nilai)","Hedging adalah strategi membuka posisi yang berlawanan dengan aset atau posisi yang Anda pegang untuk mengurangi risiko kerugian akibat pergerakan harga, dengan konsekuensi potensi untungnya ikut berkurang."],["volatility","Volatility (volatilitas)","Volatilitas adalah ukuran seberapa besar dan seberapa cepat harga sebuah aset bergerak naik turun dalam periode tertentu."],["dual-investment","Dual investment (investasi ganda)","Dual investment adalah produk terstruktur bursa yang memberi imbal hasil tinggi, tetapi saat jatuh tempo Anda bisa menerima aset yang berbeda dari yang disetor, tergantung harga terhadap target."]],"lesson":null,"coin":null,"tool":"/topics/derivatives","cta":false},"custodial-wallet":{"slug":"custodial-wallet","cat":"wallets-security","en":"Custodial wallet","contentLocale":"id","term":"Dompet kustodian (custodial wallet)","aka":["custodial wallet","wallet kustodian","dompet exchange"],"short":"Dompet kustodian adalah dompet kripto di mana pihak ketiga, biasanya exchange, menyimpan dan mengelola private key untuk Anda, sehingga Anda mengakses aset lewat akun, bukan lewat kunci sendiri.","body":[["Saat Anda menyimpan kripto di akun exchange, Anda memakai dompet kustodian. Exchange mengelola kunci, biasanya menggabungkan dana banyak pengguna di ",["dompet panas","hot-wallet"]," dan dingin miliknya, lalu mencatat saldo Anda di sistem internal. Anda login dengan email, kata sandi, dan ",["autentikasi dua faktor","two-factor-authentication"],"."],["Kelebihannya adalah kemudahan: tidak perlu menyimpan ",["seed phrase","seed-phrase"],", bisa reset akses jika lupa kata sandi, dan langsung bisa trading. Kekurangannya, Anda bergantung pada keamanan dan kejujuran penyimpan. Jika exchange diretas, membekukan akun, atau bangkrut, akses ke aset bisa terhambat atau hilang. Ungkapan populer menyebutnya: not your keys, not your coins."],["Untuk menilai kustodian, perhatikan izin dan pengawasan regulator, ",["proof of reserves","proof-of-reserves"],", dan riwayat keamanan. Di Indonesia, pedagang ",["aset kripto","cryptocurrency"]," diawasi OJK sejak Januari 2025. Perlindungan bagi pengguna berbeda di tiap negara."]],"example":["Misalkan Anda punya total 0,05 ",["BTC","bitcoin"],". Anda menyimpan 0,01 BTC di akun exchange untuk trading harian dan memindahkan 0,04 BTC ke hardware wallet. Jika suatu saat exchange menghentikan penarikan sementara, hanya 20% kepemilikan Anda yang terdampak, yaitu 0,01 dari 0,05 BTC. Sisanya 80% tetap bisa Anda pindahkan kapan saja dengan kunci sendiri, dengan konsekuensi Anda wajib menjaga seed phrase-nya."],"mistakes":["Menyimpan seluruh aset jangka panjang di satu exchange hanya karena praktis.","Tidak mengaktifkan autentikasi dua faktor dan whitelist alamat penarikan.","Mengira saldo di exchange sama dengan memiliki koin di blockchain atas nama Anda sendiri."],"faq":[{"q":"Apakah menyimpan kripto di exchange aman?","a":"Bisa cukup aman di exchange yang diawasi dan transparan, tetapi Anda tetap menanggung risiko pihak ketiga. Banyak pengguna menyimpan dana trading di exchange dan dana jangka panjang di dompet sendiri."},{"q":"Apa beda dompet kustodian dan non-kustodian?","a":"Di dompet kustodian, pihak ketiga memegang private key. Di dompet non-kustodian, Anda memegang kunci dan seed phrase sendiri, sehingga kendali dan tanggung jawab sepenuhnya ada pada Anda."}],"title":"Apa itu dompet kustodian (custodial wallet) di kripto?","description":"Pahami dompet kustodian di kripto: cara exchange menyimpan kunci Anda, kelebihan, risiko pihak ketiga, dan bedanya dengan non-kustodian.","related":[["non-custodial-wallet","Dompet non-kustodian (self-custody wallet)","Dompet non-kustodian adalah dompet kripto di mana hanya Anda yang memegang private key, sehingga tidak ada pihak lain yang bisa memindahkan, membekukan, atau memulihkan aset Anda."],["centralized-exchange","Centralized exchange (CEX)","Centralized exchange (CEX) adalah platform jual beli kripto yang dijalankan oleh sebuah perusahaan, yang menyimpan dana pengguna, mencocokkan order, dan biasanya mewajibkan verifikasi KYC."],["proof-of-reserves","Proof of reserves (bukti cadangan)","Proof of reserves adalah cara exchange membuktikan bahwa aset yang dipegangnya setidaknya sama dengan saldo yang dimiliki pengguna, biasanya dengan menunjukkan alamat dompet dan bukti Merkle tree."],["crypto-wallet","Dompet kripto (crypto wallet)","Dompet kripto adalah aplikasi, perangkat, atau layanan yang menyimpan kunci untuk mengakses aset kripto Anda di blockchain dan memungkinkan Anda menerima, mengirim, serta menandatangani transaksi."]],"lesson":{"id":"E03","slug":"exchange-vs-wallet","ep":3,"title":"Di mana koin saya? Bursa vs dompet"},"coin":null,"tool":null,"cta":false},"on-chain-analysis":{"slug":"on-chain-analysis","cat":"onchain","en":"On-chain analysis","contentLocale":"id","term":"Analisis on-chain","aka":["on-chain analysis","analisa on-chain","data on-chain"],"short":"Analisis on-chain adalah cara membaca data transaksi yang tercatat di blockchain, seperti aliran dana ke bursa, aktivitas alamat, dan pergerakan whale, untuk memahami perilaku pelaku pasar.","body":[[["Blockchain","blockchain"]," publik seperti ",["Bitcoin","bitcoin"]," dan ",["Ethereum","ethereum"]," mencatat setiap transaksi secara terbuka. Analis mengolah data ini menjadi metrik, misalnya ",["arus masuk dan keluar bursa","exchange-netflow"],", jumlah ",["alamat aktif","active-addresses"],", saldo dompet besar, biaya transaksi, atau berapa lama koin tidak dipindahkan."],["Analisis on-chain melengkapi analisis teknikal yang membaca grafik harga dan analisis fundamental yang menilai proyek. Contohnya, jika banyak BTC berpindah dari ",["dompet pribadi","non-custodial-wallet"]," ke bursa, itu bisa menandakan ada yang bersiap menjual. Namun satu metrik jarang cukup; konteks sangat penting."],"Keterbatasannya: alamat tidak selalu bisa dikaitkan dengan pemiliknya, satu bursa bisa memakai ribuan alamat, dan transaksi internal bursa tidak tercatat di blockchain. Label dari penyedia data juga bisa berbeda. Karena itu, perlakukan data on-chain sebagai petunjuk, bukan kepastian."],"example":"Misalkan dalam sehari tercatat 12.000 BTC masuk ke alamat bursa dan 8.000 BTC keluar, jadi netflow plus 4.000 BTC. Di saat yang sama, cadangan stablecoin di bursa naik 500 juta dolar. Kenaikan BTC di bursa bisa berarti tekanan jual, sementara kenaikan stablecoin bisa berarti ada dana siap membeli. Dua sinyal ini saling berlawanan, sehingga Anda perlu melihat tren beberapa hari dan grafik harga sebelum menarik kesimpulan, bukan bereaksi pada satu angka harian.","mistakes":["Mengambil keputusan dari satu metrik saja tanpa melihat konteks lain.","Menganggap setiap transfer besar ke bursa pasti diikuti penjualan.","Tidak menyadari bahwa label alamat dari penyedia data bisa keliru atau tidak lengkap."],"faq":[{"q":"Apakah analisis on-chain bisa memprediksi harga?","a":"Tidak bisa memprediksi dengan pasti. Data on-chain membantu memahami perilaku pemegang dan arus dana, tetapi harga juga dipengaruhi faktor makro, derivatif, dan sentimen."},{"q":"Data on-chain bisa dilihat di mana?","a":"Data mentah bisa dilihat lewat block explorer, sedangkan metrik olahan tersedia di platform analitik on-chain. Banyak metrik dasar bisa diakses gratis, sementara data detail biasanya berbayar."}],"title":"Apa itu analisis on-chain? Arti dan cara membacanya","description":"Pelajari analisis on-chain: metrik penting seperti arus bursa dan alamat aktif, cara membacanya, serta keterbatasannya.","related":[["exchange-netflow","Arus masuk dan keluar bursa (exchange netflow)","Exchange netflow adalah selisih antara jumlah kripto yang masuk ke dompet bursa dan yang keluar dari bursa dalam periode tertentu, dipakai untuk membaca niat jual atau simpan para pemegang."],["whale","Whale (paus kripto)","Whale adalah sebutan untuk individu atau entitas yang memegang aset kripto dalam jumlah sangat besar sehingga transaksinya berpotensi menggerakkan harga pasar."],["active-addresses","Alamat aktif (active addresses)","Alamat aktif adalah jumlah alamat blockchain unik yang mengirim atau menerima transaksi dalam periode tertentu, dipakai sebagai gambaran kasar tingkat penggunaan sebuah jaringan."],["block-explorer","Block explorer","Block explorer adalah situs atau aplikasi untuk mencari dan melihat data blockchain secara publik, seperti status transaksi, saldo alamat, isi blok, dan jumlah konfirmasi."]],"lesson":null,"coin":null,"tool":"/onchain","cta":false},"grid-trading-bot":{"slug":"grid-trading-bot","cat":"exchange-features","en":"Grid trading bot","contentLocale":"id","term":"Grid trading bot (bot grid)","aka":["grid bot","bot grid","spot grid","futures grid"],"short":"Grid trading bot adalah bot otomatis yang memasang serangkaian order beli dan jual di beberapa tingkat harga dalam satu rentang, untuk mengambil untung kecil berulang saat harga naik turun.","body":["Anda menentukan batas bawah, batas atas, dan jumlah grid. Bot membagi rentang itu menjadi beberapa tingkat. Setiap kali harga turun ke satu tingkat, bot membeli; setiap kali harga naik ke tingkat di atasnya, bot menjual. Strategi ini paling cocok untuk pasar yang bergerak menyamping dalam rentang.",["Ada dua bentuk umum: spot grid yang memakai aset sungguhan tanpa ",["leverage","leverage"],", dan futures grid yang memakai kontrak dengan leverage dan bisa diarahkan long, short, atau netral. Sebagian besar bursa besar menyediakan bot grid gratis, tetapi ",["biaya trading","maker-taker-fees"]," tetap berlaku untuk setiap order yang terisi."],["Risikonya muncul saat harga keluar dari rentang. Jika harga jatuh di bawah batas bawah, bot spot berhenti dengan sisa koin yang nilainya turun. Jika harga naik di atas batas atas, bot sudah menjual semua koin dan Anda tertinggal kenaikan. Futures grid juga bisa terkena ",["likuidasi","liquidation"],"."]],"example":["Misalkan Anda memasang spot grid ",["ETH","ethereum"]," di rentang 2.800 sampai 3.200 ",["USDT","usdt"]," dengan 8 grid, jadi jarak tiap tingkat 50 USDT. Modal 1.600 USDT dibagi rata, sekitar 200 USDT per grid. Setiap kali ETH dibeli di 2.950 lalu dijual di 3.000, keuntungan kotor sekitar 1,7% atau 3,4 USDT, dikurangi biaya trading dua sisi sekitar 0,4 USDT, jadi bersih sekitar 3 USDT. Jika dalam seminggu terjadi 20 siklus, hasilnya sekitar 60 USDT. Namun jika ETH turun ke 2.500, sisa ETH Anda mengalami kerugian yang bisa jauh lebih besar."],"mistakes":["Memasang rentang terlalu sempit sehingga harga cepat keluar dari grid.","Membuat grid terlalu rapat sehingga profit tiap siklus habis untuk biaya trading.","Mengira bot grid aman di tren turun yang kuat."],"faq":[{"q":"Apakah bot grid cocok untuk pemula?","a":"Spot grid relatif mudah dipahami karena tidak memakai leverage, tetapi Anda tetap harus memahami risiko harga keluar dari rentang. Futures grid lebih berisiko karena ada likuidasi."},{"q":"Apa yang terjadi jika harga keluar dari rentang grid?","a":"Bot berhenti bertransaksi sampai harga kembali ke rentang. Jika keluar ke bawah, Anda memegang koin yang nilainya turun; jika keluar ke atas, Anda sudah memegang USDT dan tidak ikut kenaikan lebih lanjut."}],"title":"Apa itu grid trading bot? Cara kerja bot grid kripto","description":"Pahami cara kerja grid trading bot, beda spot grid dan futures grid, cara menghitung profit per grid, dan risikonya.","related":[["dollar-cost-averaging","Dollar-cost averaging (DCA)","Dollar-cost averaging (DCA) adalah strategi membeli aset dengan nominal tetap secara berkala, misalnya setiap minggu atau bulan, tanpa memedulikan harga saat itu."],["copy-trading","Copy trading","Copy trading adalah fitur bursa yang otomatis meniru posisi trader lain, yang biasa disebut lead trader, ke akun Anda sesuai modal dan pengaturan yang Anda pilih."],["volatility","Volatility (volatilitas)","Volatilitas adalah ukuran seberapa besar dan seberapa cepat harga sebuah aset bergerak naik turun dalam periode tertentu."],["limit-order","Limit order","Limit order adalah perintah membeli atau menjual di harga tertentu yang Anda tetapkan atau lebih baik, sehingga harga terkendali tetapi order belum tentu tereksekusi."]],"lesson":null,"coin":null,"tool":null,"cta":true}});
